INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des sociétés khoïsan', 'developpement-societes-khoisan-ZA', '00001-01-01', '00299-12-31', 'Les populations san et khoïkhoï développent des sociétés de chasseurs-cueilleurs et d’éleveurs dans différentes régions de l’actuelle Afrique du Sud.', NULL, 17),
('Installation de populations bantouphones', 'installation-populations-bantouphones-ZA', '00300-01-01', '00300-12-31', 'Des populations bantouphones commencent à s’installer dans le sud de l’Afrique, notamment dans les régions orientales de l’actuelle Afrique du Sud.', NULL, 17),
('Développement du royaume de Mapungubwe', 'royaume-mapungubwe-ZA', '01075-01-01', '01220-12-31', 'Mapungubwe devient un centre politique et commercial majeur, notamment grâce au commerce de l’or et de l’ivoire avec des réseaux de l’océan Indien.', NULL, 17),
('Bartolomeu Dias atteint le cap de Bonne-Espérance', 'dias-cap-bonne-esperance-ZA', '01488-01-01', '01488-12-31', 'Le navigateur portugais Bartolomeu Dias franchit l’extrémité méridionale de l’Afrique lors de son expédition vers l’océan Indien.', NULL, 18),
('Vasco de Gama atteint la côte du Natal', 'vasco-de-gama-cote-natal-ZA', '01497-12-01', '01497-12-31', 'L’expédition de Vasco de Gama atteint la côte orientale de l’Afrique australe lors de son voyage vers l’Inde.', NULL, 18),
('Fondation de la colonie du Cap', 'fondation-colonie-cap-ZA', '01652-04-06', '01652-04-06', 'Jan van Riebeeck établit pour la Compagnie néerlandaise des Indes orientales une station de ravitaillement à Table Bay.', NULL, 16),
('Première guerre khoïkhoï-néerlandaise', 'premiere-guerre-khoikhoi-neerlandaise-ZA', '01659-01-01', '01659-12-31', 'Le premier conflit majeur oppose les populations khoïkhoï aux colons néerlandais du Cap.', NULL, 6),
('Début de l’importation d’esclaves au Cap', 'debut-esclavage-cap-ZA', '01658-01-01', '01658-12-31', 'La colonie du Cap commence à importer des personnes réduites en esclavage depuis Madagascar et l’Asie du Sud-Est.', NULL, 25),
('Arrivée des huguenots français au Cap', 'arrivee-huguenots-francais-cap-ZA', '01688-01-01', '01690-12-31', 'Des réfugiés huguenots français s’installent dans la colonie du Cap et contribuent notamment au développement de la viticulture.', NULL, 17),
('Établissement officiel de la colonie du Cap', 'etablissement-officiel-colonie-cap-ZA', '01691-01-01', '01691-12-31', 'La colonie du Cap est officiellement constituée comme colonie néerlandaise de la Compagnie des Indes orientales.', NULL, 17),
('Première occupation britannique du Cap', 'premiere-occupation-britannique-cap-ZA', '01795-09-01', '01795-09-01', 'Les forces britanniques occupent la colonie du Cap dans le contexte des guerres révolutionnaires européennes.', NULL, 13),
('Restitution du Cap à la République batave', 'restitution-cap-republique-batave-ZA', '01803-01-01', '01803-12-31', 'Le traité d’Amiens entraîne la restitution de la colonie du Cap à la République batave.', NULL, 14),
('Seconde occupation britannique du Cap', 'seconde-occupation-britannique-cap-ZA', '01806-01-08', '01806-01-08', 'Les Britanniques reprennent le contrôle de la colonie du Cap lors des guerres napoléoniennes.', NULL, 13),
('Abolition de la traite britannique des esclaves', 'abolition-traite-esclaves-britannique-ZA', '01807-03-25', '01807-03-25', 'Le Parlement britannique adopte l’abolition de la traite des esclaves dans l’Empire britannique, avec des conséquences pour la colonie du Cap.', NULL, 22),
('Cession définitive de la colonie du Cap à la Grande-Bretagne', 'cession-colonie-cap-grande-bretagne-ZA', '01814-01-01', '01814-12-31', 'Les Pays-Bas cèdent définitivement la colonie du Cap à la Grande-Bretagne.', NULL, 14),
('Création et expansion du royaume zoulou', 'creation-royaume-zoulou-ZA', '01816-01-01', '01828-12-31', 'Shaka établit et développe un puissant royaume zoulou en Afrique australe.', NULL, 16),
('Bataille de Blood River', 'bataille-blood-river-ZA', '01838-12-16', '01838-12-16', 'Les forces boers remportent une victoire contre l’armée zouloue lors de la bataille de Blood River.', NULL, 7),
('Fondation de la république de Natalia', 'fondation-republique-natalia-ZA', '01839-01-01', '01839-12-31', 'Des Voortrekkers établissent la république de Natalia dans la région de Natal.', NULL, 16),
('Convention de Sand River', 'convention-sand-river-ZA', '01852-01-17', '01852-01-17', 'La Grande-Bretagne reconnaît l’indépendance du territoire boer situé au nord du Vaal, qui devient la République sud-africaine du Transvaal.', NULL, 14),
('Fondation de l’État libre d’Orange', 'fondation-etat-libre-orange-ZA', '01854-02-23', '01854-02-23', 'La Convention de Bloemfontein reconnaît l’indépendance de l’État libre d’Orange.', NULL, 16),
('Crise du bétail xhosa', 'crise-betail-xhosa-ZA', '01856-01-01', '01857-12-31', 'Le mouvement prophétique de Nongqawuse entraîne l’abattage massif du bétail xhosa et une grave crise alimentaire et sociale.', NULL, 20),
('Découverte des diamants de Kimberley', 'decouverte-diamants-kimberley-ZA', '01867-01-01', '01867-12-31', 'La découverte de diamants dans la région de Kimberley déclenche une importante transformation économique et démographique.', NULL, 18),
('Guerre anglo-zouloue', 'guerre-anglo-zouloue-ZA', '01879-01-22', '01879-07-01', 'La guerre oppose l’Empire britannique au royaume zoulou et aboutit à la défaite du royaume zoulou.', NULL, 6),
('Première guerre des Boers', 'premiere-guerre-boers-ZA', '01880-12-16', '01881-03-23', 'Les Boers du Transvaal se soulèvent contre l’autorité britannique lors de la première guerre des Boers.', NULL, 6),
('Ruée vers l’or du Witwatersrand', 'ruee-or-witwatersrand-ZA', '01886-01-01', '01886-12-31', 'La découverte de vastes gisements d’or au Witwatersrand transforme profondément l’économie et la démographie de la région.', NULL, 18),
('Fondation de Johannesburg', 'fondation-johannesburg-ZA', '01886-01-01', '01886-12-31', 'Johannesburg se développe rapidement à la suite de la découverte de l’or dans le Witwatersrand.', NULL, 16),
('Seconde guerre des Boers', 'seconde-guerre-boers-ZA', '01899-10-11', '01902-05-31', 'La Grande-Bretagne affronte les républiques boers du Transvaal et de l’État libre d’Orange lors de la seconde guerre des Boers.', NULL, 6),
('Traité de Vereeniging', 'traite-vereeniging-ZA', '01902-05-31', '01902-05-31', 'Le traité de Vereeniging met fin à la seconde guerre des Boers et place les anciennes républiques boers sous souveraineté britannique.', NULL, 14),
('Création de l’Union sud-africaine', 'creation-union-sud-africaine-ZA', '01910-05-31', '01910-05-31', 'Les colonies du Cap, du Natal, du Transvaal et de l’État libre d’Orange sont réunies pour former l’Union sud-africaine.', NULL, 17),
('Fondation du Congrès national africain', 'fondation-congres-national-africain-ZA', '01912-01-08', '01912-01-08', 'Le South African Native National Congress, devenu l’African National Congress, est fondé pour défendre les droits politiques de la population noire.', NULL, 17),
('Natives Land Act', 'natives-land-act-ZA', '01913-06-19', '01913-06-19', 'Le Natives Land Act limite fortement l’accès des populations africaines à la propriété foncière hors des réserves désignées.', NULL, 22),
('Droit de vote des femmes blanches', 'droit-vote-femmes-blanches-ZA', '01930-01-01', '01930-12-31', 'L’Union sud-africaine accorde le droit de vote aux femmes blanches, sans instaurer un suffrage universel.', NULL, 22),
('Statut d’indépendance de l’Union sud-africaine', 'statut-independance-union-sud-africaine-ZA', '01931-12-11', '01931-12-11', 'Le Statute of Westminster reconnaît une large autonomie législative aux dominions, dont l’Union sud-africaine.', NULL, 11),
('Victoire du Parti national', 'victoire-parti-national-ZA', '01948-05-26', '01948-05-26', 'Le Parti national remporte les élections générales et commence à mettre en place l’apartheid comme politique officielle de l’État.', NULL, 22),
('Adoption du Group Areas Act', 'adoption-group-areas-act-ZA', '01950-04-27', '01950-04-27', 'Le Group Areas Act organise la séparation résidentielle des populations selon des catégories raciales.', NULL, 22),
('Campagne de défiance', 'campagne-defiance-ZA', '01952-06-26', '01952-12-31', 'Une campagne nationale de désobéissance civile contre les lois de ségrégation est lancée par des organisations opposées à l’apartheid.', NULL, 9),
('Adoption de la Charte de la liberté', 'charte-liberte-ZA', '01955-06-26', '01955-06-26', 'Le Congrès du peuple adopte à Kliptown la Charte de la liberté, qui énonce des principes pour une Afrique du Sud démocratique.', NULL, 22),
('Massacre de Sharpeville', 'massacre-sharpeville-ZA', '01960-03-21', '01960-03-21', 'La police ouvre le feu sur des manifestants à Sharpeville lors d’une mobilisation contre les lois sur les laissez-passer.', NULL, 22),
('Proclamation de la République sud-africaine', 'proclamation-republique-sud-africaine-ZA', '01961-05-31', '01961-05-31', 'L’Union sud-africaine devient la République d’Afrique du Sud à la suite du référendum constitutionnel de 1960.', NULL, 22),
('Procès de Rivonia', 'proces-rivonia-ZA', '01963-10-09', '01964-06-11', 'Le procès de Rivonia conduit à la condamnation à la prison à vie de plusieurs dirigeants de la lutte contre l’apartheid, dont Nelson Mandela.', NULL, 22),
('Première transplantation cardiaque humaine', 'premiere-transplantation-cardiaque-ZA', '01967-12-03', '01967-12-03', 'Christiaan Barnard réalise au Cap la première transplantation cardiaque humaine réussie.', NULL, 19),
('Soulèvement de Soweto', 'soulevement-soweto-ZA', '01976-06-16', '01976-12-31', 'Des manifestations étudiantes à Soweto contre la politique linguistique de l’enseignement sont réprimées violemment et déclenchent une mobilisation nationale.', NULL, 9),
('Fondation du United Democratic Front', 'fondation-united-democratic-front-ZA', '01983-08-20', '01983-08-20', 'Le United Democratic Front est créé pour coordonner de nombreuses organisations opposées à l’apartheid.', NULL, 17),
('État d’urgence de 1985', 'etat-urgence-1985-ZA', '01985-07-20', '01985-12-31', 'Le gouvernement sud-africain proclame un état d’urgence dans plusieurs régions face à l’intensification des mobilisations et des violences politiques.', NULL, 22),
('Libération de Nelson Mandela et légalisation de l’ANC', 'liberation-mandela-legalisation-anc-ZA', '01990-02-11', '01990-02-11', 'Nelson Mandela est libéré après vingt-sept années de détention et le gouvernement annonce la levée de l’interdiction de plusieurs organisations politiques.', NULL, 22),
('Adoption de la Constitution intérimaire', 'adoption-constitution-interimaire-ZA', '01993-11-18', '01993-12-22', 'Les négociations politiques aboutissent à une Constitution intérimaire qui prépare la transition vers un régime démocratique.', NULL, 22),
('Premières élections démocratiques non raciales', 'premieres-elections-democratiques-ZA', '01994-04-27', '01994-04-29', 'L’Afrique du Sud organise ses premières élections nationales au suffrage universel sans distinction raciale.', NULL, 22),
('Élection de Nelson Mandela à la présidence', 'election-nelson-mandela-president-ZA', '01994-05-09', '01994-05-09', 'Le Parlement élit Nelson Mandela président de la République d’Afrique du Sud.', NULL, 22),
('Création de la Commission vérité et réconciliation', 'creation-commission-verite-reconciliation-ZA', '01995-01-01', '01995-12-31', 'La Commission vérité et réconciliation est mise en place pour enquêter sur les violations des droits humains commises pendant la période de l’apartheid.', NULL, 22),
('Adoption de la Constitution de 1996', 'constitution-afrique-du-sud-1996-ZA', '01996-12-04', '01996-12-10', 'La nouvelle Constitution est approuvée par la Cour constitutionnelle puis signée par Nelson Mandela, établissant le cadre constitutionnel de la nouvelle Afrique du Sud.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement du royaume du Kongo', 'developpement-royaume-kongo-AO', '01390-01-01', '01400-12-31', 'Le royaume du Kongo se développe autour du bassin inférieur du Congo et exerce une influence importante sur le nord de l’actuelle Angola.', NULL, 16),
('Établissement des premiers contacts portugais avec le Kongo', 'premiers-contacts-portugais-kongo-AO', '01483-01-01', '01483-12-31', 'Les navigateurs portugais établissent des contacts avec le royaume du Kongo lors des expéditions de Diogo Cão sur la côte africaine.', NULL, 18),
('Fondation de Luanda', 'fondation-luanda-AO', '01576-01-25', '01576-01-25', 'Paulo Dias de Novais fonde Luanda comme base de l’expansion portugaise dans la région.', NULL, 16),
('Résistance de la reine Njinga', 'resistance-reine-njinga-AO', '01620-01-01', '01663-12-31', 'Njinga Mbandi dirige les royaumes de Ndongo et Matamba et organise une longue résistance à l’expansion portugaise.', NULL, 9),
('Occupation néerlandaise de Luanda', 'occupation-neerlandaise-luanda-AO', '01641-08-01', '01641-08-01', 'Les forces néerlandaises de la Compagnie néerlandaise des Indes occidentales prennent Luanda et chassent temporairement les Portugais.', NULL, 13),
('Reprise de Luanda par les Portugais', 'reprise-luanda-portugais-AO', '01648-08-15', '01648-08-15', 'Les forces portugaises commandées par Salvador Correia de Sá reprennent Luanda aux Néerlandais.', NULL, 12),
