('Révolte de Baixa de Cassanje', 'revolte-baixa-cassanje-AO', '01961-01-03', '01961-01-31', 'Une révolte des travailleurs agricoles de la région de Baixa de Cassanje contre les conditions imposées par le système colonial est durement réprimée.', NULL, 9),
('Début de la guerre d’indépendance angolaise', 'debut-guerre-independance-angola-AO', '01961-02-04', '01961-02-04', 'Des attaques contre des installations coloniales à Luanda marquent le début de la guerre d’indépendance angolaise.', NULL, 6),
('Création de l’UNITA', 'creation-unita-AO', '01966-03-13', '01966-03-13', 'Jonas Savimbi fonde l’Union nationale pour l’indépendance totale de l’Angola, qui devient l’un des principaux mouvements nationalistes angolais.', NULL, 17),
('Révolution des Œillets au Portugal', 'revolution-oeillets-portugal-angola-AO', '01974-04-25', '01974-04-25', 'Le renversement du régime portugais ouvre la voie à la fin de la guerre coloniale et aux négociations sur l’indépendance de l’Angola.', NULL, 8),
('Accords d’Alvor', 'accords-alvor-AO', '01975-01-15', '01975-01-15', 'Le Portugal, le MPLA, la FNLA et l’UNITA concluent les accords d’Alvor qui prévoient un gouvernement de transition et l’indépendance de l’Angola.', NULL, 14),
('Indépendance de l’Angola', 'independance-angola-AO', '01975-11-11', '01975-11-11', 'L’Angola proclame son indépendance du Portugal et Agostinho Neto devient le premier président du nouvel État.', NULL, 11),
('Début de la guerre civile angolaise', 'debut-guerre-civile-angola-AO', '01975-11-11', '02002-04-04', 'Après l’indépendance, le conflit entre le MPLA, l’UNITA et la FNLA se transforme en une longue guerre civile, impliquant également plusieurs puissances étrangères.', NULL, 6),
('Accords de Bicesse', 'accords-bicesse-AO', '01991-05-31', '01991-05-31', 'Les accords de Bicesse prévoient un cessez-le-feu, la transformation des forces armées et l’organisation d’élections multipartites.', NULL, 14),
('Protocole de Lusaka et fin de la guerre civile', 'protocole-lusaka-fin-guerre-civile-AO', '02002-04-04', '02002-04-04', 'La mort de Jonas Savimbi et la signature du mémorandum de Luena mettent fin aux principales hostilités et ouvrent la voie à la paix en Angola.', NULL, 14);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Fondation du royaume du Dahomey', 'fondation-royaume-dahomey-BJ', '01620-01-01', '01620-12-31', 'Le royaume du Dahomey se forme sur le plateau d’Abomey et devient progressivement une puissance majeure de la région.', NULL, 16),
