('Création du Parti démocratique du Botswana', 'creation-parti-democratique-botswana-BW', '01962-01-01', '01962-01-01', 'Seretse Khama et ses alliés fondent le Botswana Democratic Party, qui participe à la transition politique vers l’autonomie.', NULL, 17),
('Autonomie interne du Bechuanaland', 'autonomie-interne-bechuanaland-BW', '01965-03-01', '01965-03-01', 'Le Bechuanaland devient autonome avec un gouvernement élu dirigé par Seretse Khama comme Premier ministre.', NULL, 22),
('Transfert de la capitale à Gaborone', 'transfert-capitale-gaborone-BW', '01965-01-01', '01965-01-01', 'Le siège du gouvernement est transféré de Mafikeng à Gaborone, nouvelle capitale située à l’intérieur du territoire du protectorat.', NULL, 22),
('Indépendance du Botswana', 'independance-botswana-BW', '01966-09-30', '01966-09-30', 'Le Bechuanaland devient la République indépendante du Botswana et Seretse Khama devient son premier président.', NULL, 11),
('Découverte des diamants d’Orapa', 'decouverte-diamants-orapa-BW', '01967-07-01', '01967-07-01', 'D’importants gisements de diamants sont découverts à Orapa, ouvrant une nouvelle période économique pour le Botswana.', NULL, 18),
('Adhésion du Botswana à l’Organisation des Nations unies', 'adhesion-botswana-onu-BW', '01966-10-17', '01966-10-17', 'Le Botswana devient membre de l’Organisation des Nations unies peu après son indépendance.', NULL, 15);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
