('Prise de Djenné par Sonni Ali', 'prise-djenne-sonni-ali-ML', '01473-01-01', '01473-12-31', 'Sonni Ali conquiert Djenné et consolide le contrôle songhaï sur les principaux centres commerciaux du Niger.', NULL, 12),
('Conquête marocaine de Tombouctou', 'conquete-marocaine-tombouctou-ML', '01591-04-13', '01591-04-13', 'Les troupes marocaines remportent la bataille de Tondibi et prennent le contrôle de Tombouctou et de Gao.', NULL, 12),
('Conquête de Ségou par El Hadj Omar Tall', 'conquete-segou-el-hadj-omar-tall-ML', '01861-03-10', '01861-03-10', 'El Hadj Omar Tall conquiert Ségou et met fin au royaume bambara de Ségou.', NULL, 12),
('Indépendance du Mali', 'independance-mali-ML', '01960-09-22', '01960-09-22', 'La République soudanaise devient indépendante sous le nom de République du Mali.', NULL, 11);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des cités antiques du nord du Maroc', 'developpement-cites-antiques-nord-maroc-MA', '00001-01-01', '00200-12-31', 'Les cités du nord du Maroc se développent autour des échanges méditerranéens et des activités agricoles et artisanales.', NULL, 16),
('Développement de Volubilis', 'developpement-volubilis-MA', '00001-01-01', '00300-12-31', 'Volubilis devient un important centre urbain et agricole de la Maurétanie occidentale puis de la province romaine de Maurétanie Tingitane.', NULL, 16),
('Annexion de la Maurétanie Tingitane par Rome', 'annexion-mauretanie-tingitane-rome-MA', '00042-01-01', '00042-12-31', 'Après la mort du roi Ptolémée de Maurétanie, Rome annexe son royaume et organise la Maurétanie Tingitane comme province.', NULL, 12),
('Révolte d’Aedemon contre Rome', 'revolte-aedemon-rome-MA', '00040-01-01', '00044-12-31', 'Aedemon mène une révolte contre l’annexion romaine de la Maurétanie après la mort de Ptolémée.', NULL, 9),
('Diffusion du christianisme au Maroc antique', 'diffusion-christianisme-maroc-antique-MA', '00200-01-01', '00400-12-31', 'Le christianisme se diffuse progressivement dans plusieurs communautés urbaines de la Maurétanie Tingitane.', NULL, 23),
('Conquête vandale de l’Afrique du Nord', 'conquete-vandale-afrique-nord-MA', '00429-01-01', '00439-12-31', 'Les Vandales conquièrent une grande partie de l’Afrique du Nord et bouleversent l’organisation politique de la région.', NULL, 12),
('Conquête byzantine de la Maurétanie Tingitane', 'conquete-byzantine-mauretanie-tingitane-MA', '00533-01-01', '00534-12-31', 'Les Byzantins reprennent plusieurs territoires d’Afrique du Nord aux Vandales, sans toutefois contrôler durablement tout le Maroc actuel.', NULL, 12),
('Conquête arabe du Maghreb occidental', 'conquete-arabe-maghreb-occidental-MA', '00680-01-01', '00705-12-31', 'Les armées arabes progressent vers l’ouest du Maghreb et établissent progressivement leur domination sur le territoire marocain.', NULL, 12),
('Révolte berbère contre le califat omeyyade', 'revolte-berbere-califat-omeyyade-MA', '00739-01-01', '00743-12-31', 'Une vaste révolte berbère éclate au Maghreb contre les autorités omeyyades et remet en cause leur domination.', NULL, 9),
('Fondation de l’émirat idrisside', 'fondation-emirat-idrisside-MA', '00788-01-01', '00788-12-31', 'Idris Ier fonde une dynastie qui établit un pouvoir autonome dans le nord du Maroc.', NULL, 16),
('Fondation de Fès', 'fondation-fes-MA', '00789-01-01', '00808-12-31', 'Idris Ier puis Idris II développent Fès, qui devient la capitale et un important centre politique et religieux.', NULL, 16),
('Développement de la dynastie almoravide', 'developpement-dynastie-almoravide-MA', '01040-01-01', '01147-12-31', 'Les Almoravides unifient une grande partie du Maghreb occidental et étendent leur pouvoir jusqu’à la péninsule Ibérique.', NULL, 12),
('Fondation de Marrakech', 'fondation-marrakech-MA', '01067-01-01', '01070-12-31', 'Les Almoravides fondent Marrakech, qui devient un centre politique majeur de leur empire.', NULL, 16),
('Conquête almohade du Maroc', 'conquete-almohade-maroc-MA', '01147-01-01', '01147-12-31', 'Les Almohades prennent Marrakech et mettent fin au pouvoir almoravide au Maroc.', NULL, 12),
('Développement de la dynastie mérinide', 'developpement-dynastie-merinide-MA', '01260-01-01', '01460-12-31', 'Les Mérinides établissent leur pouvoir au Maroc et font de Fès un important centre politique et culturel.', NULL, 5),
('Fondation de la dynastie saadienne', 'fondation-dynastie-saadienne-MA', '01514-01-01', '01514-12-31', 'La dynastie saadienne s’impose progressivement dans le sud du Maroc et prend ensuite le contrôle du royaume.', NULL, 16),
('Bataille des Trois Rois', 'bataille-trois-rois-MA', '01578-08-04', '01578-08-04', 'Les forces marocaines remportent une victoire décisive contre l’armée portugaise et ses alliés lors de la bataille d’Alcácer-Quibir.', NULL, 7),
('Fondation de la dynastie alaouite', 'fondation-dynastie-alaouite-MA', '01660-01-01', '01660-12-31', 'La dynastie alaouite consolide progressivement son pouvoir et rétablit l’unité politique du Maroc.', NULL, 16),
('Traité de Fès et établissement du protectorat français', 'traite-fes-protectorat-francais-MA', '01912-03-30', '01912-03-30', 'Le traité de Fès établit le protectorat français sur le Maroc tout en maintenant officiellement le sultanat.', NULL, 14),
('Indépendance du Maroc', 'independance-maroc-MA', '01956-03-02', '01956-03-02', 'Le Maroc met fin au protectorat français et retrouve son indépendance sous le règne de Mohammed V.', NULL, 11);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Premières occupations humaines de l’île Maurice', 'premieres-occupations-humaines-ile-maurice-MU', '01500-01-01', '01500-12-31', 'Les premières occupations humaines permanentes de l’île Maurice se développent avec l’arrivée de populations et de navigateurs de l’océan Indien.', NULL, 16),
('Découverte de l’île Maurice par les Portugais', 'decouverte-ile-maurice-portugais-MU', '01505-01-01', '01505-12-31', 'Les navigateurs portugais atteignent l’île Maurice au début du XVIe siècle et l’intègrent aux cartes de l’océan Indien.', NULL, 18),
('Première présence portugaise dans l’océan Indien occidental', 'presence-portugaise-ocean-indien-occidental-MU', '01505-01-01', '01600-12-31', 'Les Portugais utilisent progressivement les îles de l’océan Indien occidental comme points de navigation et de ravitaillement.', NULL, 13),
('Prise de possession néerlandaise de Maurice', 'prise-possession-neerlandaise-maurice-MU', '01598-09-17', '01598-09-17', 'Les Provinces-Unies prennent possession de l’île et lui donnent le nom de Mauritius en l’honneur du prince Maurice de Nassau.', NULL, 12),
('Début de la colonisation néerlandaise de Maurice', 'debut-colonisation-neerlandaise-maurice-MU', '01638-01-01', '01638-12-31', 'Les Néerlandais établissent une colonie permanente à Maurice et développent progressivement l’exploitation de l’île.', NULL, 16),
('Introduction de la canne à sucre à Maurice', 'introduction-canne-sucre-maurice-MU', '01630-01-01', '01630-12-31', 'Les Néerlandais introduisent la canne à sucre à Maurice, qui devient progressivement une culture importante.', NULL, 19),
('Départ définitif des Néerlandais', 'depart-neerlandais-maurice-MU', '01710-01-01', '01710-01-01', 'Les Néerlandais abandonnent définitivement leur colonie de Maurice après plusieurs décennies de difficultés économiques et environnementales.', NULL, 22),
('Prise de possession française de l’île Maurice', 'prise-possession-francaise-maurice-MU', '01715-01-01', '01715-01-01', 'La France prend possession de l’île et lui redonne le nom d’Île de France.', NULL, 12),
('Développement de Port-Louis', 'developpement-port-louis-MU', '01730-01-01', '01730-12-31', 'Port-Louis se développe comme principal port et centre administratif de l’île sous administration française.', NULL, 16),
